    # centers that are proper pluses
    def is_plus(g,p,v):
        r,c=p
        if not(0<r<H-1 and 0<c<W-1): return False
        return g[r-1,c]==3 and g[r+1,c]==3 and g[r,c-1]==3 and g[r,c+1]==3
    centers=[(r,c,v) for r,c,v in plus if is_plus(g,(r,c),v)]
    empties=[(r,c) for r,c in map(tuple, np.argwhere(g==0)) if is_plus(g,(r,c),0)]
    # arms of proper pluses (incl empty)
    arms=set()
    for r,c,v in centers:
        arms |= {(r-1,c),(r+1,c),(r,c-1),(r,c+1)}
    for r,c in empties:
        arms |= {(r-1,c),(r+1,c),(r,c-1),(r,c+1)}
    # draw rows then columns (columns win), skipping proper arms
    for r,c,v in centers:
        for j in range(W):
            if (r,j) not in arms: out[r,j]=v
    for r,c,v in centers:
        for i in range(H):
            if (i,c) not in arms: out[i,c]=v
    # empty plus lines (color 0), columns beat rows: apply after columns, before rows?
    for r,c in empties:
        for i in range(H):
            if (i,c) not in arms: out[i,c]=0
        for j in range(W):
            if (r,j) not in arms: out[r,j]=0
    return out

