def predict2(inp):
    g=inp.copy(); H,W=g.shape
    out=np.zeros_like(g)
    # find pluses: centers with 4 symmetric arms
    centers=[]
    for r in range(1,H-1):
        for c in range(1,W-1):
            if g[r-1,c]==3 and g[r+1,c]==3 and g[r,c-1]==3 and g[r,c+1]==3 and g[r,c]!=3:
                centers.append((r,c,int(g[r,c])))
    arms=set()
    for r,c,v in centers:
        arms|={(r-1,c),(r+1,c),(r,c-1),(r,c+1)}
    centers_nonempty=[(r,c,v) for r,c,v in centers if v!=0]
    empties=[(r,c) for r,c,v in centers if v==0]
    all_plus_cells = arms | {(r,c) for r,c,v in centers}
    # rays from each digit center; stop before foreign plus cells
    for r,c,v in centers_nonempty:
        # left
        for j in range(c-1,-1,-1):
            if (r,j) in all_plus_cells and (r,j) not in {(r,c-1)}: break
            out[r,j]=v
        for j in range(c+1,W):
            if (r,j) in all_plus_cells and (r,j) not in {(r,c+1)}: break
            out[r,j]=v
        for i in range(r-1,-1,-1):
            if (i,c) in all_plus_cells and (i,c) not in {(r-1,c)}: break
            out[i,c]=v
        for i in range(r+1,H):
            if (i,c) in all_plus_cells and (i,c) not in {(r+1,c)}: break
            out[i,c]=v
    # columns beat rows: redraw column rays over row rays at crossings
    for r,c,v in centers_nonempty:
        for i in range(H): 
            if (i,c) not in all_plus_cells: out[i,c]=v
    # place pluses back (centers + arms)
    for r,c,v in centers: out[r,c]=v
    for (a,b) in arms: out[a,b]=3
    # empty plus: punch 0-holes in its column (except its own cells / arms)
    for r,c in empties:
        for i in range(H):
            if (i,c) not in all_plus_cells: out[i,c]=0
    return out

